SELECT rating_bucket, rating_range, country_values FROM (SELECT CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(rating) - MIN(rating) AS rating_range, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(country))) AS country_values FROM suppliers GROUP BY CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END) AS x WHERE rating_range < 47
